def match_stock_by_pinyin(query: str, stock_list: list) -> list:
    """
    根据拼音首字母匹配股票
    
    Args:
        query: 用户输入的拼音首字母（如 'tkgf'）
        stock_list: 股票列表，每个元素是 (code, name) 元组
    
    Returns:
        匹配的股票列表
    """
    query = query.lower()
    matches = []
    
    for code, name in stock_list:
        # 获取股票名称的拼音首字母
        name_initials = get_pinyin_initials(name)
        
        # 检查是否匹配
        if query in name_initials or query in code.lower():
            matches.append((code, name))
    
    return matches
